/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Types: Receipt, Asset
 *   Functions: revive, read, load, canonical, dto, receiptBody, embeddedOperationId
 *   Constants: actor, otherAdmin, fixtureDirectory, candidates, environment, previous, dtoGoldens
 * Tests
 *   - every v1 fixture is a purpose-less import accepted by the current manifest, draft and asset readers
 *   - a created v1 draft keeps one artistName string, track titles and numbers, and one create receipt
 *   - a completed v1 analysis keeps its baseline and leaves the artistName suggestion pending
 *   - reviewed v1 assets hold per-file embedded cover candidates beside ready audio and explicit decisions
 *   - v1 reuse decisions name exact candidate revisions for the reviewed Artist, Album and Track
 *   - v1 publication states project their recovery, cleanup and completed catalog identities
 *   - a v1 publication into an existing Album keeps the candidate revisions commitPublication re-checks
 * @end-catalog */

/**
 * Freezes the v1 administrator-import documents in test/fixtures/adminImport. Each fixture is relaxed MongoDB
 * Extended JSON reconstructed from today's create, analysis-worker, upload, review, publication and
 * cancellation code paths with synthetic identities and a fixed clock (not captured from a live database);
 * its IDs, receipt hashes, chunk hashes and suggestions are recomputed below from the exported helpers. These
 * tests prove the current parsers, validators, DTO projection and storage reader accept every fixture
 * unchanged, so the later Draft v2, Disc Number and multi-artist changes can rely on them as the stored v1
 * shapes they must keep reading.
 */
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readdirSync, readFileSync } from 'node:fs';
import { after, before, test } from 'node:test';
import { ObjectId } from 'mongodb';
// The database module loads first; importing adminImportService before it trips the index import cycle.
import '../../src/infrastructure/database';
import { legacyDefaultDraftV1, parseDraft, parseManifest, uuid } from '../../src/administration/import/adminImportContract';
import { validateAnalysisSuggestions } from '../../src/administration/import/adminImportProvider';
import { adminImportDto, importCandidateProjection, importCandidateRevision, importDigest, isImportProject, type AdminImportDocument } from '../../src/administration/import/adminImportService';
import { importAssetTarget } from '../../src/administration/import/adminImportStorage';
import { sortTrackIdsByEmbeddedTrackNumber } from '../../src/services/catalog/albumTrackLinkService';

type Receipt = AdminImportDocument['receipts'][number];
type Asset = NonNullable<AdminImportDocument['media']>['assets'][number];
const actor = '0000000000000000000000a1', otherAdmin = '0000000000000000000000a2';
// Fixtures are relaxed MongoDB Extended JSON; v1 documents use only the $oid and $date wrappers.
const revive = (_key: string, value: unknown) => {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return value;
    const wrapped = value as { $oid?: string; $date?: string };
    return typeof wrapped.$oid === 'string' ? new ObjectId(wrapped.$oid) : typeof wrapped.$date === 'string' ? new Date(wrapped.$date) : value;
};
const fixtureDirectory = new URL('../fixtures/adminImport/', import.meta.url);
const read = (name: string) => JSON.parse(readFileSync(new URL(name, fixtureDirectory), 'utf8'), revive);
const load = (name: string) => read(name) as AdminImportDocument;
const candidates = read('v1-duplicate-candidates.json') as Record<'artists' | 'albums' | 'audioTracks', Record<string, any>[]>;
// Key-sorted so a DTO golden changes with projected content, not with property declaration order.
const canonical = (value: unknown): unknown => Array.isArray(value) ? value.map(canonical) : value && typeof value === 'object' ? Object.fromEntries(Object.keys(value).sort().map(key => [key, canonical((value as Record<string, unknown>)[key])])) : value;
const dto = (doc: AdminImportDocument, viewer = actor) => adminImportDto(doc, viewer, true);
const environment = { FINITUDE_ADMIN_IMPORTS_ENABLED: 'true', FINITUDE_ADMIN_IMPORT_PRIVATE_STORAGE_READY: 'true', ADMIN_IMPORT_S3_BUCKET_NAME: 'synthetic-private-imports', S3_BUCKET_NAME: 'synthetic-catalog' };
const previous = Object.fromEntries(Object.keys(environment).map(key => [key, process.env[key]]));
before(() => { Object.assign(process.env, environment); });
after(() => { for (const [key, value] of Object.entries(previous)) { if (value === undefined) delete process.env[key]; else process.env[key] = value; } });

/**
 * Rebuilds the request body a stored receipt fingerprints. mutateAdminProject digests { kind, body } in
 * request key order, so a replay with the same intent must reproduce the stored hash exactly.
 */
const receiptBody = (doc: AdminImportDocument, receipt: Receipt): Record<string, unknown> => {
    const base = { operationId: receipt.operationId, expectedRevision: receipt.revision - 1 };
    switch (receipt.kind) {
        case 'analyze': case 'publish': return base;
        case 'upload': { const asset = doc.media!.assets.find(item => item.operationId === receipt.operationId)!; return { ...base, slotId: asset.slotId, sha256: asset.sha256, byteLength: asset.byteLength, contentType: asset.contentType }; }
        case 'decisions': return { ...base, decisions: doc.decisions };
        case 'select-cover': return { ...base, slotId: doc.media!.selectedCoverSlotId };
        case 'cancel-publication': return { ...base, publicationOperationId: doc.media!.publication!.operationId };
        case 'adopt': return { ...base, generation: receipt.selection!.generation, selectedIds: receipt.selection!.acceptedIds, rejectIds: receipt.selection!.rejectedIds };
        default: throw new Error(`no v1 fixture body for receipt kind ${receipt.kind}`);
    }
};
/** Embedded artwork reuses its audio upload intent through the UUID uploadAdminImportAsset derives. */
const embeddedOperationId = (audio: Asset) => {
    const hash = importDigest({ operationId: audio.operationId, embedded: audio.slotId });
    return `${hash.slice(0, 8)}-${hash.slice(8, 12)}-4${hash.slice(13, 16)}-8${hash.slice(17, 20)}-${hash.slice(20, 32)}`;
};

/** Golden sha256 of each fixture's full canonical admin DTO, computed from the pre-change code. */
const dtoGoldens: Record<string, string> = {
    'v1-draft.json': 'ad08238ba4428a004f771fe5b3d025a1bcd4d187a19171476dfb193c0b8cb71d',
    'v1-analysis-pending-artist-name.json': 'f8a68f40c06e38b256a26c095ba00213ec65477d7ba5006dc9709362d06c9d8d',
    'v1-assets-reviewed.json': 'f233c4901efab92fc6fa080b7bbff8866c3e237eb2a8c3d81806849608f4cb77',
    'v1-decisions-album-reuse.json': '0275de91289f6a746dc9f6c7b12ce94e677709e0cfbafc049ffa0f1d6c8a170d',
    'v1-publication-preparing.json': 'e26e2610732f6f453e1e3f62c7baf8621d20f9dafa2780ee094e638ca9d18698',
    'v1-publication-needs-attention.json': '80d2e78e2c53ad2e840d3c7f4504317b719b99c3ab7ed7717c8ee4b52c35bf5b',
    'v1-publication-cancelled-cleanup-pending.json': 'aea45c384031ea1a00ec30d74d8203c308eb4bb5b3abbaeb837d73a899cf920a',
    'v1-publication-complete.json': 'c65baa3c3fd799b75ac08014b4f74c68f4786cb1cd7a4f0511d85e73ebbdb276',
    'v1-publication-complete-album-reuse.json': '5441cce6c1e9fda262e4e80fc864064395d84eb6269d4cf1bb166a8fe67ec184'
};

test('every v1 fixture is a purpose-less import accepted by the current manifest, draft and asset readers', () => {
    // Every import fixture in the folder carries a golden; the candidate rows are checked by the reuse test.
    assert.deepEqual(readdirSync(fixtureDirectory).sort(), [...Object.keys(dtoGoldens), 'v1-duplicate-candidates.json'].sort());
    for (const [name, golden] of Object.entries(dtoGoldens)) {
        const doc = load(name), id = doc._id.toHexString(), [create] = doc.receipts, assets = doc.media?.assets ?? [];
        assert.equal(isImportProject(doc), true, name); assert.equal('purpose' in doc, false, name);
        assert.deepEqual(parseManifest(doc.manifest), doc.manifest, name); assert.deepEqual(parseDraft(doc.draft, doc.manifest), doc.draft, name);
        for (const draft of [doc.analysis.baseline, doc.media?.publication?.snapshot]) if (draft) assert.deepEqual(parseDraft(draft, doc.manifest), draft, name);
        // createAdminImport derives the _id and replay hash; fixtures change a draft only by adopting
        // analysis, so the creation draft is the analysis baseline when one exists.
        assert.equal(id, importDigest({ actor, operationId: create.operationId }).slice(0, 24), name);
        assert.equal(create.hash, importDigest({ kind: 'create', manifest: doc.manifest, draft: doc.analysis.baseline ?? doc.draft, operationId: create.operationId }), name);
        for (const receipt of [...doc.receipts.slice(1), ...(doc.recoveryReceipts ?? [])]) assert.equal(receipt.hash, importDigest({ kind: receipt.kind, body: receiptBody(doc, receipt) }), `${name} ${receipt.kind}@${receipt.revision}`);
        const revisions = [...doc.receipts, ...(doc.recoveryReceipts ?? [])].map(receipt => receipt.revision);
        assert.deepEqual(revisions, [...revisions].sort((a, b) => a - b), name); assert.ok(revisions[revisions.length - 1] <= doc.revision, name);
        for (const asset of assets) {
            assert.equal(uuid(asset.operationId), true, name);
            assert.deepEqual(importAssetTarget(id, asset), { bucket: 'synthetic-private-imports', key: `imports/${id}/${asset.slotId}/${asset.operationId}`, sha256: asset.sha256, byteLength: asset.byteLength, contentType: asset.contentType, importId: id, slotId: asset.slotId, operationId: asset.operationId }, name);
            const receipt = doc.receipts.find(item => item.kind === 'upload' && item.operationId === asset.operationId)!;
            assert.deepEqual(asset.recovery, { operationId: asset.operationId, expectedRevision: receipt.revision - 1, kind: 'upload', actorId: actor }, name);
            if (asset.slotId.startsWith('embedded-')) assert.equal(asset.operationId, embeddedOperationId(assets.find(item => `embedded-${item.slotId}` === asset.slotId)!), name);
        }
        const projected = JSON.stringify(canonical(dto(doc)));
        assert.equal(createHash('sha256').update(projected).digest('hex'), golden, `${name}: ${projected}`);
    }
});

test('a created v1 draft keeps one artistName string, track titles and numbers, and one create receipt', () => {
    const doc = load('v1-draft.json'), item = dto(doc);
    assert.equal(item.draft.album.artistName, 'Lorem Ensemble & Ipsum Quartet');
    assert.deepEqual(item.draft.tracks.map(track => [track.title, track.trackNumber]), [['Lorem Opening', 1], ['Ipsum Interlude', 2]]);
    assert.deepEqual(item.receipts, [{ operationId: '00000001-0000-4000-8000-000000000001', kind: 'create', revision: 1 }]);
    assert.deepEqual([item.analysis.state, item.publication, item.publicationRecovery, item.assets, item.upload], ['idle', 'notStarted', null, [], { ready: 0, total: 2, available: true }]);
});

test('a completed v1 analysis keeps its baseline and leaves the artistName suggestion pending', () => {
    const doc = load('v1-analysis-pending-artist-name.json'), item = dto(doc), { analysis } = doc, baseline = analysis.baseline!;
    // The baseline is the draftless default of its time (hidden); defaultDraft is public now, so compare the frozen value.
    assert.deepEqual(baseline, legacyDefaultDraftV1(doc.manifest));
    assert.deepEqual(item.analysis, { state: 'complete', generation: 1, operationId: '00000002-0000-4000-8000-000000000002', completedChunks: 2, totalChunks: 2, attemptsUsed: 2, maxAttempts: 22, issue: null });
    const pending = item.suggestions.filter(suggestion => suggestion.decision === 'pending');
    assert.deepEqual(pending.map(({ scope, slotId, field, baseline, value, source }) => ({ scope, slotId, field, baseline, value, source })), [{ scope: 'album', slotId: null, field: 'artistName', baseline: '', value: 'Synthetic Artist', source: 'folder' }]);
    assert.deepEqual(item.suggestions.map(suggestion => suggestion.decision).sort(), ['accepted', 'accepted', 'accepted', 'accepted', 'accepted', 'accepted', 'pending', 'rejected']);
    assert.deepEqual([item.draft.album.artistName, item.draft.tracks.map(track => track.trackNumber)], ['', [1, 2, null]]);
    assert.deepEqual(doc.receipts.map(receipt => [receipt.kind, receipt.revision, receipt.selection?.acceptedIds.length ?? null, receipt.selection?.rejectedIds.length ?? null]), [['create', 1, null, null], ['analyze', 2, null, null], ['adopt', 7, 6, 1]]);
    // Replays each chunk through the worker's derivations: the chunk hash, the per-chunk provider input that
    // validateAnalysisSuggestions accepts, and the suggestion ids the worker assigns by chunk and position.
    assert.deepEqual(analysis.tags, []);
    let replayed = 0;
    for (const chunk of analysis.chunks) {
        assert.equal(chunk.hash, importDigest({ generation: analysis.generation, manifest: doc.manifest, baseline, tags: analysis.tags, slots: chunk.slots, album: chunk.album }), `chunk ${chunk.index}`);
        const stored = doc.suggestions.filter(suggestion => chunk.album ? suggestion.scope === 'album' : suggestion.scope === 'track' && chunk.slots.includes(suggestion.slotId!));
        const raw = { suggestions: stored.map(({ scope, slotId, field, value, source, evidence }) => ({ scope, slotId, field, text: typeof value === 'string' ? value : null, number: typeof value === 'number' ? value : null, date: value !== null && typeof value === 'object' ? value : null, source, evidence })) };
        const input = { generation: analysis.generation, chunk: chunk.index, manifest: { rootLabel: doc.manifest.rootLabel, files: chunk.album ? doc.manifest.files : doc.manifest.files.filter(file => chunk.slots.includes(file.slotId)) },
            baseline: { album: baseline.album, tracks: chunk.album ? [] : baseline.tracks.filter(track => chunk.slots.includes(track.slotId)) }, slots: chunk.slots, album: chunk.album, tags: [] };
        assert.deepEqual(validateAnalysisSuggestions(raw, input), stored.map(({ scope, slotId, field, baseline, value, source, evidence }) => ({ scope, slotId, field, baseline, value, source, evidence })), `chunk ${chunk.index}`);
        stored.forEach((suggestion, index) => {
            assert.equal(suggestion.generation, analysis.generation);
            assert.equal(suggestion.id, importDigest({ importId: doc._id.toHexString(), generation: analysis.generation, chunk: chunk.index, index }).slice(0, 24), `chunk ${chunk.index} #${index}`);
        });
        replayed += stored.length;
    }
    assert.equal(replayed, doc.suggestions.length);
});

test('reviewed v1 assets hold per-file embedded cover candidates beside ready audio and explicit decisions', () => {
    const doc = load('v1-assets-reviewed.json'), item = dto(doc), [first, second, third] = doc.manifest.files.map(file => file.slotId);
    assert.deepEqual(item.assets.map(asset => [asset.slotId, asset.state, asset.contentType, asset.tags === null]), [[first, 'ready', 'audio/mpeg', false], [`embedded-${first}`, 'ready', 'image/jpeg', true], [second, 'ready', 'audio/mpeg', false], [`embedded-${second}`, 'ready', 'image/jpeg', true], [third, 'ready', 'audio/mpeg', false]]);
    assert.equal(item.selectedCoverSlotId, `embedded-${second}`); assert.deepEqual(item.upload, { ready: 3, total: 3, available: true });
    assert.deepEqual(item.decisions.map(decision => [decision.scope, decision.slotId, decision.action]), [['artist', null, 'create-distinct'], ['album', null, 'create-distinct'], ['track', first, 'create-distinct'], ['track', second, 'create-distinct'], ['track', third, 'create-distinct']]);
    assert.deepEqual([item.publication, item.capabilities], ['notStarted', { analysis: true, upload: true, publish: true }]);
});

test('v1 reuse decisions name exact candidate revisions for the reviewed Artist, Album and Track', () => {
    const doc = load('v1-decisions-album-reuse.json'), rows = { artist: candidates.artists, album: candidates.albums, track: candidates.audioTracks };
    for (const row of Object.values(rows).flat()) assert.deepEqual(Object.keys(row).filter(key => key !== '_id' && !(key in importCandidateProjection)), []);
    const reused = doc.decisions.filter(decision => decision.action === 'reuse');
    assert.deepEqual(reused.map(decision => decision.scope), ['artist', 'album', 'track']);
    for (const decision of reused) assert.equal(importCandidateRevision(rows[decision.scope].find(row => row._id.toHexString() === decision.candidateId)!), decision.candidateRevision);
    assert.equal(candidates.audioTracks[0].albumId, candidates.albums[0]._id.toHexString()); assert.equal(candidates.albums[0].credits[0].subjectId, candidates.artists[0]._id.toHexString());
    assert.deepEqual(doc.decisions.filter(decision => decision.scope === 'track').map(decision => [doc.manifest.files.findIndex(file => file.slotId === decision.slotId), decision.action]), [[1, 'reuse'], [2, 'create-distinct'], [0, 'skip']]);
});

test('v1 publication states project their recovery, cleanup and completed catalog identities', () => {
    // [fixture, DTO state, cleanupPending, track states once published, manifest index of each Album track]
    const cases = [
        ['v1-publication-preparing.json', 'preparing', false, null, [1, 2, 0]],
        ['v1-publication-needs-attention.json', 'needsAttention', false, null, [1, 2, 0]],
        ['v1-publication-cancelled-cleanup-pending.json', 'cancelled', true, null, [1, 2, 0]],
        ['v1-publication-complete.json', 'complete', false, ['ready', 'ready', 'ready'], [1, 2, 0]],
        ['v1-publication-complete-album-reuse.json', 'complete', false, ['ready', 'ready'], [1, 2]]
    ] as const;
    for (const [name, state, cleanupPending, published, order] of cases) {
        const doc = load(name), publication = doc.media!.publication!, item = dto(doc);
        assert.equal(item.publication, state, name); assert.deepEqual(item.publicationRecovery, { operationId: publication.operationId, cleanupPending, startedByMe: true }, name);
        assert.deepEqual([publication.snapshot, publication.decisions], [doc.draft, doc.decisions], name);
        // Album order follows draft trackNumber, not manifest order (Disc 2 first), and the stored v1 order
        // must still be what the current catalog ordering rule yields from the approved snapshot numbers.
        assert.deepEqual(publication.tracks.map(track => doc.manifest.files.findIndex(file => file.slotId === track.slotId)), order, name);
        const ids = publication.tracks.map(track => track.id);
        assert.deepEqual(ids, sortTrackIdsByEmbeddedTrackNumber(ids, new Map(publication.tracks.map(track => [track.id, publication.snapshot.tracks.find(item => item.slotId === track.slotId)!.trackNumber]))), name);
        assert.deepEqual(item.published && publication.tracks.map(track => track.state), published, name);
        assert.equal(dto(doc, otherAdmin).publicationRecovery!.startedByMe, false, name);
    }
    const needsAttention = load('v1-publication-needs-attention.json').media!.publication!, cancelled = load('v1-publication-cancelled-cleanup-pending.json').media!.publication!, complete = load('v1-publication-complete.json');
    assert.deepEqual([needsAttention.issue, needsAttention.tracks.map(track => track.state), needsAttention.cover!.state], ['storageUnknown', ['ready', 'unknown', 'pending'], 'pending']);
    assert.deepEqual([cancelled.issue, cancelled.cancellation?.actorId, cancelled.tracks.map(track => track.cleanupComplete ?? false)], ['storageUnknown', actor, [true, false, false]]);
    const publication = complete.media!.publication!;
    assert.deepEqual(dto(complete).published, { albumId: publication.albumId, artistId: '0000000000000000000000c1', trackIds: publication.tracks.map(track => track.id) });
    assert.deepEqual([publication.newArtist, publication.newAlbum, publication.cover!.slotId, publication.cover!.state], [false, true, complete.media!.selectedCoverSlotId, 'ready']);
});

test('a v1 publication into an existing Album keeps the candidate revisions commitPublication re-checks', () => {
    const doc = load('v1-publication-complete-album-reuse.json'), publication = doc.media!.publication!, [artist] = candidates.artists, [album] = candidates.albums, [track] = candidates.audioTracks;
    // The publisher rejects a new cover for an existing Album, so none is selected or copied.
    assert.deepEqual([publication.newArtist, publication.artistId, publication.newAlbum, publication.albumId, publication.coverId, publication.cover, doc.media!.selectedCoverSlotId ?? null], [false, artist._id.toHexString(), false, album._id.toHexString(), null, null, null]);
    assert.equal(publication.albumRevision, importCandidateRevision(album));
    const [reused, created] = publication.tracks;
    assert.deepEqual([reused.id, reused.key, reused.reused, reused.candidateRevision, reused.state, reused.etag], [track._id.toHexString(), '', true, importCandidateRevision(track), 'ready', null]);
    assert.deepEqual([created.reused, created.candidateRevision, created.state, created.key.startsWith(`audio/${created.id}/`)], [false, null, 'ready', true]);
    assert.deepEqual(dto(doc).published, { albumId: album._id.toHexString(), artistId: artist._id.toHexString(), trackIds: [track._id.toHexString(), created.id] });
});
